// === Tab: mySketch ===
// ORANGE VIOLENCE
// Made for Raph's WCCChallenge.

// If needed, press M to toggle manual controls. Then space to trigger the cutting.

let currentShape = [[-1,-1],[1,-0.8],[0.8,1],[-1,1]];
let oldShape = [];
let oldCut = [[10,0],[10,0]];
let posX = 0;
let posY = 0;
let velX = 0;
let velY = -1;
let dt = 0.01;
let mindim;

let cutterState = 1;
let stateTimer = 0;
let cutPoints = [[0,0],[0,0]];
let manualMode = false;
let manualTrigger = false;

let sizeFactor = 0.45;
let cameraShiftX = 0.2;
let cameraShiftY = 0.0;
let cameraMomentum = 0;
let deterioration = 0;

function setup() {
	createCanvas(windowWidth, windowHeight);
	mindim = max(width, height);
}

function cutPoint_to_xy(cutPoint){
	let i = cutPoint[0];
	let j = (i+1)%currentShape.length;
	let t = cutPoint[1];
	let side_dx = currentShape[j][0] - currentShape[i][0];
	let side_dy = currentShape[j][1] - currentShape[i][1]; 
	return [currentShape[i][0]*(1-t) + currentShape[j][0]*t, currentShape[i][1]*(1-t) + currentShape[j][1]*t];
}

function render(){
	background(245);
	noStroke();
	fill(255,200,40);
	beginShape();
	for(let v of currentShape){
		vertex(width/2 + mindim*sizeFactor*(v[0]+cameraShiftX), height/2 + mindim*sizeFactor*(v[1]+cameraShiftY));
	}
	endShape();

	stroke(245);
	strokeWeight(8);
	if(cutterState >= 2){
		let cutPoint1 = cutPoint_to_xy(cutPoints[0]);
		let cutPoint2 = [posX, posY];
		if(cutterState == 3){
			cutPoint2 = cutPoint_to_xy(cutPoints[1]);
			cutPoint2[0] += (cutPoint2[0]-cutPoint1[0])*0.1;
			cutPoint2[1] += (cutPoint2[1]-cutPoint1[1])*0.1;
		}
		cutPoint1[0] += (cutPoint1[0]-cutPoint2[0])*0.1;
		cutPoint1[1] += (cutPoint1[1]-cutPoint2[1])*0.1;
		line(width/2 + mindim*sizeFactor*(cutPoint1[0]+cameraShiftX),height/2 + mindim*sizeFactor*(cutPoint1[1]+cameraShiftY), width/2 + mindim*sizeFactor*(cutPoint2[0]+cameraShiftX),height/2 + mindim*sizeFactor*(cutPoint2[1]+cameraShiftY));
	}

	beginShape();
	noStroke();
	fill(255,200+40*deterioration,40+130*deterioration);
	for(let v of oldShape){
		vertex(width/2 + mindim*sizeFactor*(v[0]+cameraShiftX), height/2 + mindim*sizeFactor*(v[1]+cameraShiftY));
	}
	endShape();

	stroke(245);
	strokeWeight(8);
	if(cutterState >= 0){
		var cutPoint1 = [...oldCut[0]];
		var cutPoint2 = [...oldCut[1]];
		cutPoint2[0] += (cutPoint2[0]-cutPoint1[0])*0.1;
		cutPoint2[1] += (cutPoint2[1]-cutPoint1[1])*0.1;
		cutPoint1[0] += (cutPoint1[0]-cutPoint2[0])*0.1;
		cutPoint1[1] += (cutPoint1[1]-cutPoint2[1])*0.1;
		line(width/2 + mindim*sizeFactor*(cutPoint1[0]+cameraShiftX),height/2 + mindim*sizeFactor*(cutPoint1[1]+cameraShiftY), width/2 + mindim*sizeFactor*(cutPoint2[0]+cameraShiftX),height/2 + mindim*sizeFactor*(cutPoint2[1]+cameraShiftY));
	}

	if(cutterState==0 || cutterState==3)stroke(200,140,20);
	fill(255,200,40);
	ellipse(width/2 + mindim*sizeFactor*(posX+cameraShiftX), height/2 + mindim*sizeFactor*(posY+cameraShiftY),24);
	adjustCamera();
	deterioration += (1-deterioration)*0.02;
}

function adjustCamera(){
	let defect = min(sqrt(cameraShiftX*cameraShiftX + cameraShiftY*cameraShiftY) + abs(sizeFactor-0.45)/3, 0.3);
	cameraMomentum += defect/3;
	cameraShiftX *= (1-cameraMomentum*0.1);
	cameraShiftY *= (1-cameraMomentum*0.1);
	sizeFactor += (0.45-sizeFactor)*0.01*cameraMomentum;
	cameraMomentum *= 0.92;
}

function update(){
	stateTimer++;
	posX += velX*dt;
	posY += velY*dt;
	for(let i=0; i<currentShape.length; i++){
		var j = (i+1)%currentShape.length;
		var side_dx = currentShape[j][0] - currentShape[i][0];
		var side_dy = currentShape[j][1] - currentShape[i][1];
		let p_dx = posX - currentShape[i][0];
		let p_dy = posY - currentShape[i][1];
		if(side_dx*p_dy - side_dy*p_dx < 0 && side_dx*velY - side_dy*velX < 0){

			let proj_n = side_dx*velY - side_dy*velX;
			let proj_t = side_dx*velX + side_dy*velY;
			velX = proj_t*side_dx + proj_n*side_dy;
			velY = proj_t*side_dy - proj_n*side_dx;
			let mag = sqrt(velX*velX + velY*velY);
			velX /= mag;
			velY /= mag;
			if(cutterState == 1 || cutterState == 2){
				let sideLSq = side_dx*side_dx + side_dy*side_dy;
				let sideLength = sqrt(sideLSq);
				let overstep = -(side_dy*p_dx - side_dx*p_dy)/proj_n*proj_t;
				var t = (side_dx*p_dx + side_dy*p_dy - overstep*(cutterState*2-3))/sideLSq;
				cutPoints[cutterState-1] = [i, t];
				if(cutPoints[cutterState-1][1]>0.02 && cutPoints[cutterState-1][1]<0.98){
					cutterState += 1;
					stateTimer = 0;
				}else{
					cutterState = 1;
					stateTimer = 0;
				}
			}
			posX += velX*dt;
			posY += velY*dt;
		}
	}
	if(cutterState == 3){
		if((!manualMode && random()<0.01 && stateTimer>200) || manualTrigger&&manualMode){
			manualTrigger = false;
			cutterState = 0;
			stateTimer = 0;
			processSplit();
		}
	}
	if(cutterState == 0){
		if((!manualMode && random()<0.008 && stateTimer>130) || manualTrigger&&manualMode){
			manualTrigger = false;
			stateTimer = 0;
			cutterState = 1;
		}
	}
}

function processSplit(){
	if(cutPoints[0][0] == cutPoints[1][0])return;
	var cutPoint1 = cutPoint_to_xy(cutPoints[0]);
	var cutPoint2 = cutPoint_to_xy(cutPoints[1]);
	leftShape = [];
	rightShape = [];
	leftShape.push(cutPoint1);
	rightShape.push(cutPoint2);
	let cv = currentShape.length;
	for(let i=cutPoints[0][0]; i!=cutPoints[1][0]; i = (i+1)%cv){
		leftShape.push(currentShape[(i+1)%cv]);
	}
	for(let i=cutPoints[1][0]; i!=cutPoints[0][0]; i = (i+1)%cv){
		rightShape.push(currentShape[(i+1)%cv]);
	}
	leftShape.push(cutPoint2);
	rightShape.push(cutPoint1);
	// print(leftShape);
	// print(rightShape);

	let split_dx = cutPoint2[0] - cutPoint1[0];
	let split_dy = cutPoint2[1] - cutPoint1[1];
	var p_dx = posX - cutPoint1[0];
	var p_dy = posY - cutPoint1[1];
	if(p_dx*split_dy - p_dy*split_dx < 0){
		currentShape = shapeCopy(rightShape);
		oldShape = shapeCopy(leftShape);
	}else{
		currentShape = shapeCopy(leftShape);
		oldShape = shapeCopy(rightShape);
	}
	oldCut = [cutPoint1, cutPoint2];
	deterioration = 0;
	normalizeShape();
}

function shapeCopy(shape){
	return shape.map(v => [...v]);
}

function normalizeShape(){
	let minX = currentShape[0][0];
	let maxX = currentShape[0][0];
	let minY = currentShape[0][1];
	let maxY = currentShape[0][1];
	for(let v of currentShape){
		if(v[0]<minX)minX=v[0];
		if(v[0]>maxX)maxX=v[0];
		if(v[1]<minY)minY=v[1];
		if(v[1]>maxY)maxY=v[1];
	}
	let shift_x = -(maxX+minX)/2;
	let shift_y = -(maxY+minY)/2;
	let greaterSpan = max((maxX-minX), (maxY-minY));
	let scale = 2/greaterSpan;
	for(let v of currentShape){
		v[0] = (v[0]+shift_x)*scale;
		v[1] = (v[1]+shift_y)*scale;
	}
	for(let v of oldShape){
		v[0] = (v[0]+shift_x)*scale;
		v[1] = (v[1]+shift_y)*scale;
	}
	for(let v of oldCut){
		v[0] = (v[0]+shift_x)*scale;
		v[1] = (v[1]+shift_y)*scale;
	}
	posX = (posX+shift_x)*scale;
	posY = (posY+shift_y)*scale;
	cameraTrick(shift_x, shift_y, scale);
}

function cameraTrick(tx, ty, z){
	sizeFactor *= 1/z;
	cameraShiftX *= z;
	cameraShiftY *= z;
	cameraShiftX -= tx*z;
	cameraShiftY -= ty*z;
}

function draw() {
	render();
	for(let i=0; i<4; i++)
	update();
}

function keyPressed(){
	if(key=='m'){
		manualMode = !manualMode;
	}
	if(manualMode && key==' '){
		manualTrigger = true;
	}
}
